const PackedDialog* dialog_for_sprite(int sprite_id) {
  for (const PackedDialog& d : kDialogs)
    if (d.sprite_id == sprite_id) return &d;
  return nullptr;
}

std::span<const PackedDialog> all_dialogs() { return kDialogs; }
